def subjects_groups_to_inline(apps, schema_editor):
    """Перенос предметов и групп со страниц в инлайн-модели.

    Раньше каждый предмет/группа был отдельной страницей (SubjectPage/GroupPage)
    с полями прямо на странице. Теперь они хранятся инлайном на страницах-
    справочниках. Поэтому:
      1. для каждой SubjectPage создаём SubjectModel (name=title, description);
      2. для каждой GroupPage создаём GroupModel (name=title, куратор);
      3. в расписании (StreamField schedule) ссылки subject/groups со старых
         pk страниц переставляем на pk новых инлайн-моделей.

    Студентов (GroupStudent) перепривязываем отдельным шагом после смены FK.
    """
    db_alias = schema_editor.connection.alias

    SubjectPage = apps.get_model("home", "SubjectPage")
    SubjectModel = apps.get_model("home", "SubjectModel")
    GroupPage = apps.get_model("home", "GroupPage")
    GroupModel = apps.get_model("home", "GroupModel")
    SchedulePage = apps.get_model("home", "SchedulePage")

    # --- Предметы ---
    subject_map = {}  # pk страницы -> pk SubjectModel
    for page in SubjectPage.objects.using(db_alias).order_by("path"):
        subject = SubjectModel.objects.using(db_alias).create(
            subject_page_id=page.pk,
            name=page.title,
            description=page.description,
            sort_order=len(subject_map),
        )
        subject_map[page.pk] = subject.pk

    # --- Группы ---
    group_map = {}  # pk страницы -> pk GroupModel
    for index, page in enumerate(GroupPage.objects.using(db_alias).order_by("path")):
        group = GroupModel.objects.using(db_alias).create(
            group_page_id=page.pk,
            name=page.title,
            curator_name=page.curator_name,
            curator_email=page.curator_email,
            curator_phone=page.curator_phone,
            sort_order=index,
        )
        group_map[page.pk] = group.pk

    if not subject_map and not group_map:
        return

    # --- Расписание: перепривязка ссылок subject/groups ---
    for schedule in SchedulePage.objects.using(db_alias):
        raw = schedule.schedule
        if not raw:
            continue
        data = list(raw.raw_data)
        changed = False
        for day in data:
            if day.get("type") != "day":
                continue
            for lesson in day.get("value", {}).get("lessons", []):
                if lesson.get("type") != "lesson":
                    continue
                value = lesson["value"]
                if value.get("subject") in subject_map:
                    value["subject"] = subject_map[value["subject"]]
                    changed = True
                groups = value.get("groups") or []
                new_groups = [group_map.get(g, g) for g in groups]
                if new_groups != groups:
                    value["groups"] = new_groups
                    changed = True
        if changed:
            schedule.schedule = data
            schedule.save(using=db_alias)


def reparent_group_students(apps, schema_editor):
    """Перепривязка студентов со страниц GroupPage на группы GroupModel.

    Выполняется ПОСЛЕ смены FK GroupStudent.group -> GroupModel. Каждой
    странице-группе соответствует ровно один GroupModel (созданный на её pk),
    поэтому старое значение group_id (pk страницы) заменяем на pk GroupModel,
    у которого group_page_id равен pk страницы.
    """
    db_alias = schema_editor.connection.alias

    GroupStudent = apps.get_model("home", "GroupStudent")
    GroupModel = apps.get_model("home", "GroupModel")

    # pk страницы -> pk GroupModel (group_model.group_page_id == pk страницы)
    page_to_model = {
        gm.group_page_id: gm.pk for gm in GroupModel.objects.using(db_alias)
    }
    if not page_to_model:
        return

    for student in GroupStudent.objects.using(db_alias):
        new_group_pk = page_to_model.get(student.group_id)
        if new_group_pk is not None and new_group_pk != student.group_id:
            student.group_id = new_group_pk
            student.save(using=db_alias)


